param(
    [string]$ProjectRoot = "E:\MY PROJECT FOLDER\AURA PROJECT\AURA-Butler-Android-Studio-v0.4.0-Native-Stable",
    [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "AURA v0.15.3 DeepResearch visibility hotfix" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Project: $ProjectRoot"
Write-Host ""
Write-Host "This hotfix repairs only the Kotlin visibility error:" -ForegroundColor Yellow
Write-Host "  public searchLiteEvidence() exposed internal LiteResearchEvidence"
Write-Host ""
Write-Host "The method is internal-only and is called only inside the Android app module,"
Write-Host "so this patch changes the method visibility to internal."
Write-Host ""
Write-Host "Cloud v0.15.3 already deployed successfully and Lite Search already passed."
Write-Host "This script does NOT redeploy Modal and does NOT consume cloud/GPU budget."
Write-Host ""

$AndroidRoot = Join-Path $ProjectRoot "android"
$TargetFile = Join-Path $AndroidRoot "app\src\main\java\in\diganta\aurabutler\data\DeepResearchProvider.kt"
$Gradlew = Join-Path $AndroidRoot "gradlew.bat"

if (-not (Test-Path -LiteralPath $TargetFile)) {
    throw "Target file not found: $TargetFile"
}
if (-not (Test-Path -LiteralPath $Gradlew)) {
    throw "Gradle wrapper not found: $Gradlew"
}

$ExpectedHash = "402D69000B4B301453A0EF7A38531C14DEB3041E4BA196BBD7DED501D917B303"
$TargetHash = "3AC1C7902EB1048F7B55440AEB4DCA670F2B7C34D64096E86B050F4897B64100"
$CurrentHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $TargetFile).Hash.ToUpperInvariant()

Write-Host "Current DeepResearchProvider.kt SHA256: $CurrentHash"

if ($CurrentHash -eq $TargetHash) {
    Write-Host "CURRENT: visibility repair is already installed." -ForegroundColor Green
}
elseif ($CurrentHash -eq $ExpectedHash) {
    $Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $Backup = "$TargetFile.backup-$Stamp"
    Copy-Item -LiteralPath $TargetFile -Destination $Backup -Force
    Write-Host "Backup: $Backup"

    $Encoded = @'

'@

    [System.IO.File]::WriteAllBytes(
        $TargetFile,
        [System.Convert]::FromBase64String($Encoded.Trim())
    )

    $After = (Get-FileHash -Algorithm SHA256 -LiteralPath $TargetFile).Hash.ToUpperInvariant()
    if ($After -ne $TargetHash) {
        throw "Write verification failed. Expected $TargetHash but got $After"
    }

    Write-Host "PATCHED: DeepResearchProvider.kt" -ForegroundColor Green
}
else {
    throw @"
Refusing to overwrite an unexpected DeepResearchProvider.kt.

Expected current v0.15.3 SHA256:
$ExpectedHash

Corrected SHA256:
$TargetHash

Actual SHA256:
$CurrentHash

Do not force this patch. Send the actual hash for review.
"@
}

$Text = [System.IO.File]::ReadAllText($TargetFile)

if (-not $Text.Contains("internal data class LiteResearchEvidence(")) {
    throw "LiteResearchEvidence is no longer internal as expected."
}
if (-not $Text.Contains("internal suspend fun searchLiteEvidence(")) {
    throw "Correct internal searchLiteEvidence() declaration is missing."
}

Write-Host "PASS [static]: internal API visibility is consistent" -ForegroundColor Green

if ($SkipBuild) {
    Write-Host ""
    Write-Host "SkipBuild requested. Source repaired; Gradle was not run." -ForegroundColor Yellow
    exit 0
}

foreach ($Candidate in @(
    "E:\Program Files\Android\Android Studio\jbr",
    "C:\Program Files\Android\Android Studio\jbr"
)) {
    if (Test-Path -LiteralPath (Join-Path $Candidate "bin\java.exe")) {
        $env:JAVA_HOME = $Candidate
        break
    }
}

Write-Host ""
Write-Host "==> Android verification" -ForegroundColor Cyan
Write-Host "Tasks: testDebugUnitTest lintDebug assembleDebug"
Write-Host ""

Push-Location $AndroidRoot
try {
    & $Gradlew --no-daemon testDebugUnitTest lintDebug assembleDebug
    $GradleExit = $LASTEXITCODE
}
finally {
    Pop-Location
}

if ($GradleExit -ne 0) {
    throw "Gradle verification failed with exit code $GradleExit. Send the first FAILED task."
}

Write-Host ""
Write-Host "PASS: JVM unit tests" -ForegroundColor Green
Write-Host "PASS: Android lintDebug" -ForegroundColor Green
Write-Host "PASS: Debug APK build" -ForegroundColor Green

$BuiltApk = Join-Path $AndroidRoot "app\build\outputs\apk\debug\app-debug.apk"
if (-not (Test-Path -LiteralPath $BuiltApk)) {
    throw "Gradle succeeded but app-debug.apk was not found."
}

$FinalApk = Join-Path $ProjectRoot "AURA-v0.15.3-smart-failover-debug-fixed.apk"
Copy-Item -LiteralPath $BuiltApk -Destination $FinalApk -Force

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host "SUCCESS: AURA v0.15.3 Android build passed." -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "APK: $FinalApk"
Write-Host ""
Write-Host "Install this APK as an UPDATE; do not uninstall AURA first."
Write-Host "No Modal redeployment is needed."
